import json
import re
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"error": "Could not import the supplied evidence helper", "exception": type(exc).__name__, "detail": str(exc)}))
    sys.exit(1)

TARGET = "192.168.5.10"

def stdout_text(value):
    """Collect stdout fields from a helper envelope without interpreting tool results."""
    found = []
    def walk(item):
        if isinstance(item, dict):
            for key, child in item.items():
                if key == "stdout" and isinstance(child, str):
                    found.append(child)
                else:
                    walk(child)
        elif isinstance(item, list):
            for child in item:
                walk(child)
    walk(value)
    return "\n".join(found)

result = {
    "search_query": ["msfconsole", "-q", "-x", "search type:auxiliary nginx; exit"],
    "search": None,
    "candidate_module_paths_from_search_output": [],
    "candidate_inspections": [],
    "limitations": []
}

try:
    search = run_tool(result["search_query"])
    result["search"] = search
except Exception as exc:
    result["limitations"].append({"stage": "search", "exception": type(exc).__name__, "detail": str(exc)})
    print(json.dumps(result, ensure_ascii=False, default=str))
    sys.exit(0)

search_text = stdout_text(search)
# Extract only auxiliary scanner module paths printed in the search output.
paths = sorted(set(re.findall(r"\b(auxiliary/scanner/[A-Za-z0-9_./-]+)", search_text)))
result["candidate_module_paths_from_search_output"] = paths
if not search_text:
    result["limitations"].append({"stage": "search", "detail": "No stdout text was available to inspect for module paths; consult the retained search envelope."})

for module in paths:
    # Module names are constrained by the extraction expression before being placed in -x.
    command = ["msfconsole", "-q", "-x", "info " + module + "; use " + module + "; show options; exit"]
    entry = {"module": module, "inspection_command": command, "inspection": None, "rhosts_configuration": None}
    try:
        inspection = run_tool(command)
        entry["inspection"] = inspection
        options_text = stdout_text(inspection)
        # Only configure the observed target when this module's returned information/options mention RHOSTS.
        if re.search(r"\bRHOSTS\b", options_text, re.IGNORECASE):
            config_command = ["msfconsole", "-q", "-x", "use " + module + "; set RHOSTS " + TARGET + "; show options; exit"]
            entry["rhosts_configuration_command"] = config_command
            try:
                entry["rhosts_configuration"] = run_tool(config_command)
            except Exception as exc:
                entry["rhosts_configuration_error"] = {"exception": type(exc).__name__, "detail": str(exc)}
        else:
            entry["rhosts_configuration_note"] = "RHOSTS was not found in the available inspection stdout; no target value was set."
    except Exception as exc:
        entry["inspection_error"] = {"exception": type(exc).__name__, "detail": str(exc)}
    result["candidate_inspections"].append(entry)

print(json.dumps(result, ensure_ascii=False, default=str))

