import json
import re
import sys

try:
    import framework_evidence
except Exception as exc:
    print(json.dumps({"evidence_version": 1, "status": "helper_unavailable", "error": str(exc)}))
    sys.exit(1)

runs = []

def run(argv):
    try:
        result = framework_evidence.run_tool(argv)
    except Exception as exc:
        result = {"command": argv, "status": "wrapper_error", "error": str(exc)}
    runs.append(result)
    return result

# Search broadly for nginx references, then explicitly constrain a second
# search to auxiliary modules. The semicolon is interpreted by msfconsole,
# not by a shell.
search_commands = [
    "search nginx; exit",
    "search type:auxiliary nginx; exit",
]
search_results = [run(["msfconsole", "-q", "-x", command]) for command in search_commands]

module_pattern = re.compile(r"^\s*\d+\s+(auxiliary/[^\s]+)", re.MULTILINE)
candidates = set()
for result in search_results:
    stdout = result.get("stdout", "") if isinstance(result, dict) else ""
    for module in module_pattern.findall(stdout):
        if "nginx" in module.lower() and "/scanner/" in module.lower():
            candidates.add(module)

# Inspect every nginx-related auxiliary scanner module identified in usable
# search output. Module names are accepted only from the constrained pattern.
info_results = []
for module in sorted(candidates):
    info_results.append(run(["msfconsole", "-q", "-x", "info " + module + "; exit"]))

print(json.dumps({
    "evidence_version": 1,
    "search_queries": search_commands,
    "parsed_nginx_scanner_candidates": sorted(candidates),
    "candidate_extraction": "parsed_from_search_stdout; an empty list is not proof of no match if search output was incomplete or unparseable",
    "tool_runs": runs,
}, ensure_ascii=False))

