import json
import re
import sys


def emit(value):
    print(json.dumps(value, ensure_ascii=False, default=str))


def output_text(value):
    """Collect actual stdout fields from the helper envelope for candidate selection."""
    pieces = []
    if isinstance(value, dict):
        if isinstance(value.get("stdout"), str):
            pieces.append(value["stdout"])
        runs = value.get("tool_runs")
        if isinstance(runs, list):
            for run in runs:
                pieces.extend(output_text(run))
        for key in ("structured_output", "result"):
            if key in value:
                pieces.extend(output_text(value[key]))
    elif isinstance(value, list):
        for item in value:
            pieces.extend(output_text(item))
    return pieces


def main():
    try:
        from framework_evidence import run_tool
    except Exception as exc:
        emit({"status": "helper_import_error", "error": str(exc)})
        return 2

    queries = [
        "search type:auxiliary scanner/http",
        "search type:auxiliary http",
    ]
    search_envelopes = []
    combined = []
    for query in queries:
        argv = ["msfconsole", "-q", "-x", query + "; exit -y"]
        try:
            envelope = run_tool(argv)
        except Exception as exc:
            emit({"status": "tool_invocation_error", "command": argv, "error": str(exc)})
            continue
        emit(envelope)
        search_envelopes.append(envelope)
        combined.extend(output_text(envelope))

    text = "\n".join(combined)
    modules = set(re.findall(r"auxiliary/scanner/http/[A-Za-z0-9_./-]+", text))
    # Focus on scanner candidates relevant to web-server or common HTTP weaknesses;
    # omit the previously examined nginx-only source-disclosure module.
    relevant = re.compile(
        r"(version|apache|iis|tomcat|travers|disclos|vuln|cve|inject|upload|put|"
        r"backup|options|trace|directory|files|proxy|shellshock|struts|webdav)",
        re.IGNORECASE,
    )
    candidates = sorted(
        name.rstrip(".,;:)")
        for name in modules
        if relevant.search(name)
        and name.lower() != "auxiliary/scanner/http/nginx_source_disclosure"
    )[:15]

    if candidates:
        commands = ["info " + name for name in candidates]
        argv = ["msfconsole", "-q", "-x", "; ".join(commands) + "; exit -y"]
        try:
            emit(run_tool(argv))
        except Exception as exc:
            emit({"status": "tool_invocation_error", "command": argv, "error": str(exc)})
    else:
        emit({
            "status": "no_candidate_names_parsed",
            "note": "Search envelopes above are the evidence; no matching scanner module names could be extracted from their captured stdout.",
        })
    return 0


if __name__ == "__main__":
    sys.exit(main())

