import json
import re
import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"status": "helper_import_error", "error": str(exc)}))
    raise SystemExit(1)

EXCLUDED = {
    "auxiliary/scanner/http/nginx_source_disclosure",
    "auxiliary/scanner/http/trace",
    "auxiliary/scanner/http/host_header_injection",
}
RELEVANCE = re.compile(
    r"vuln|cve|injection|disclosure|traversal|upload|put|auth|overflow|"
    r"denial|dos|smuggl|misconfig|weak|expos|rce|remote.code",
    re.IGNORECASE,
)
MODULE_RE = re.compile(r"auxiliary/scanner/http/[A-Za-z0-9_./-]+")


def envelope_stdout(envelope):
    if not isinstance(envelope, dict):
        return ""
    runs = envelope.get("tool_runs")
    if isinstance(runs, list):
        return "\n".join(
            str(run.get("stdout", ""))
            for run in runs
            if isinstance(run, dict)
        )
    return str(envelope.get("stdout", ""))


def invoke(label, command):
    argv = ["msfconsole", "-q", "-x", command]
    try:
        result = run_tool(argv)
        print(json.dumps({"label": label, "argv": argv, "evidence": result},
                         ensure_ascii=False))
        return result
    except Exception as exc:
        print(json.dumps({"label": label, "argv": argv,
                          "execution_error": str(exc)}, ensure_ascii=False))
        return None


# Search the HTTP scanner collection and a security-focused query. Both are
# module discovery only; no module is configured to contact the target.
search_results = []
for label, command in (
    ("http_scanner_search", "search type:auxiliary scanner http; exit"),
    ("http_vulnerability_search", "search type:auxiliary scanner http vuln; exit"),
):
    result = invoke(label, command)
    if result is not None:
        search_results.append((label, result))

candidates = {}
for label, result in search_results:
    text = envelope_stdout(result)
    for match in MODULE_RE.finditer(text):
        module = match.group(0).rstrip(".,;:")
        if module in EXCLUDED:
            continue
        # Search-table text near the module path often describes the module.
        # Include candidates with security-check language or names, and retain
        # the entire raw search envelope for independent review.
        start = max(0, match.start() - 220)
        end = min(len(text), match.end() + 260)
        context = text[start:end]
        if RELEVANCE.search(module) or RELEVANCE.search(context):
            candidates.setdefault(module, set()).add(label)

print(json.dumps({
    "candidate_modules_selected_for_inspection": [
        {"module": module, "found_in_searches": sorted(labels)}
        for module, labels in sorted(candidates.items())
    ],
    "excluded_modules": sorted(EXCLUDED),
    "selection_note": "Candidates were selected from raw search output using security-check terms; the search envelopes above preserve the complete returned evidence. No candidate is treated as vulnerable based on its name or search listing."
}, ensure_ascii=False))

for module in sorted(candidates):
    command = "info " + module + "; use " + module + "; show options; exit"
    invoke("inspect_" + module, command)

if not candidates:
    print(json.dumps({
        "inspection_result": "No distinct candidate matching the selection terms was extracted from the available search output.",
        "interpretation": "This is limited to the returned search text and its parsing; it does not prove no other Metasploit scanner exists."
    }))

