import sys

try:
    from framework_evidence import run_tool
except Exception as exc:
    print(json.dumps({"status": "helper_import_error", "error": str(exc)}))
    sys.exit(1)

EXCLUDED = {
    "auxiliary/scanner/http/nginx_source_disclosure",
    "auxiliary/scanner/http/trace",
    "auxiliary/scanner/http/host_header_injection",
}
SEARCHES = [
    "type:auxiliary name:http",
    "type:auxiliary name:vuln",
    "type:auxiliary name:range",
]
# Names suggesting a scanner that may test a vulnerability or risky HTTP behavior.
INDICATORS = re.compile(
    r"vuln|disclos|dos|injection|travers|overflow|range|smuggl|cache|"
    r"cve|webdav|put|proxy|request|method|header|nginx|apache|iis|tomcat",
    re.IGNORECASE,
)
MODULE_RE = re.compile(r"\b(auxiliary/scanner/http/[A-Za-z0-9_./-]+)\b")


def strings_named_stdout(value):
    """Yield raw stdout strings without interpreting tool status as findings."""
    if isinstance(value, dict):
        for key, child in value.items():
            if key == "stdout" and isinstance(child, str):
                yield child
            else:
                yield from strings_named_stdout(child)
    elif isinstance(value, list):
        for child in value:
            yield from strings_named_stdout(child)


def invoke(msf_command):
    return run_tool(["msfconsole", "-q", "-x", msf_command])

search_results = []
candidate_paths = set()
for query in SEARCHES:
    envelope = invoke("search " + query + "; exit")
    search_results.append({"query": query, "raw_envelope": envelope})
    for stdout in strings_named_stdout(envelope):
        for path in MODULE_RE.findall(stdout):
            if path not in EXCLUDED and INDICATORS.search(path.rsplit("/", 1)[-1]):
                candidate_paths.add(path)

inspections = []
for module in sorted(candidate_paths):
    # Paths come from Metasploit output and are constrained by MODULE_RE.
    command = "info " + module + "; use " + module + "; show options; exit"
    inspections.append({"module": module, "raw_envelope": invoke(command)})

print(json.dumps({
    "target_context": {
        "host": "192.168.5.10",
        "port": 80,
        "observed_server": "nginx/1.11.13",
        "observed_responses": ["HTTP 404", "TRACE returned HTTP 405"],
    },
    "search_results": search_results,
    "candidate_paths_selected_for_inspection": sorted(candidate_paths),
    "candidate_inspections": inspections,
    "interpretation_note": (
        "Search and module metadata are discovery evidence, not proof of target vulnerability. "
        "Only observed target address and HTTP port are available as grounded endpoint parameters; "
        "other required values must be supported by the captured observations."
    ),
}, ensure_ascii=False))

