import json
import re

import framework_evidence


def emit(value):
    print(json.dumps(value, sort_keys=True))


def stdout_from_envelope(envelope):
    """Extract available stdout without replacing or discarding the raw envelope."""
    if not isinstance(envelope, dict):
        return ""
    runs = envelope.get("tool_runs")
    if isinstance(runs, list):
        return "\n".join(
            run.get("stdout", "")
            for run in runs
            if isinstance(run, dict) and isinstance(run.get("stdout", ""), str)
        )
    if isinstance(envelope.get("stdout"), str):
        return envelope["stdout"]
    return ""


def main():
    search_argv = [
        "msfconsole",
        "-q",
        "-x",
        "search nginx type:auxiliary; exit",
    ]
    search_result = framework_evidence.run_tool(search_argv)
    emit({"stage": "nginx_anchored_auxiliary_search", "raw_tool_envelope": search_result})

    output = stdout_from_envelope(search_result)
    # Restrict follow-up inspection to auxiliary scanner modules named in the
    # actual search output; do not infer candidates from the expected result.
    candidates = sorted(set(re.findall(r"\bauxiliary/scanner/[A-Za-z0-9_./-]+", output)))
    candidates = [candidate.rstrip("/.-") for candidate in candidates]

    if not candidates:
        emit({
            "stage": "candidate_selection",
            "identified_auxiliary_scanner_modules": [],
            "note": (
                "No auxiliary/scanner module path was identified in captured search stdout. "
                "This is not a negative finding if the tool failed, output was unavailable, "
                "or the search output format could not be parsed."
            ),
        })
        return

    emit({"stage": "candidate_selection", "identified_auxiliary_scanner_modules": candidates})
    for module in candidates:
        # info and show options are inspection only; no target is configured and
        # no check, run, or exploit command is issued.
        commands = f"info {module}; use {module}; show options; back; exit"
        result = framework_evidence.run_tool(["msfconsole", "-q", "-x", commands])
        emit({
            "stage": "module_description_and_options",
            "module": module,
            "raw_tool_envelope": result,
        })


if __name__ == "__main__":
    main()

