import framework_evidence


def run_console(command, stage):
    argv = ["msfconsole", "-q", "-x", command + "; exit"]
    try:
        envelope = framework_evidence.run_tool(argv)
        print(json.dumps({"stage": stage, "raw_tool_envelope": envelope}, sort_keys=True))
        return envelope
    except Exception as exc:
        print(json.dumps({"stage": stage, "command": argv, "error": str(exc)}, sort_keys=True))
        return None


def tool_stdout(envelope):
    if not isinstance(envelope, dict):
        return ""
    for run in envelope.get("tool_runs", []):
        if isinstance(run, dict) and isinstance(run.get("stdout"), str):
            return run["stdout"]
    return ""


searches = [
    ("version_anchored_search", "search type:auxiliary nginx 1.11.13"),
    ("https_tls_anchored_search", "search type:auxiliary nginx ssl"),
]
