import framework_evidence


def tool_text(value):
    parts = []
    if isinstance(value, dict):
        for key, item in value.items():
            if key in ("stdout", "stderr") and isinstance(item, str):
                parts.append(item)
            else:
                parts.extend(tool_text(item))
    elif isinstance(value, list):
        for item in value:
            parts.extend(tool_text(item))
    return parts


def run_and_record(argv):
    try:
        envelope = framework_evidence.run_tool(argv)
        print(json.dumps(envelope, ensure_ascii=False, sort_keys=True))
        return envelope
    except Exception as exc:
        error = {"command": argv, "status": "exception", "error": str(exc)}
        print(json.dumps(error, ensure_ascii=False, sort_keys=True))
        return error


search_terms = ("ssl", "tls")
