    search_envelopes.append(
        run_and_record(["msfconsole", "-q", "-x", "search type:auxiliary " + term + "; exit"])
    )

candidates = set()
module_pattern = re.compile(r"\b(auxiliary/[A-Za-z0-9_./-]+)")
for envelope in search_envelopes:
    for text in tool_text(envelope):
        for match in module_pattern.finditer(text):
            module = match.group(1).rstrip(".,;:")
            lowered = module.lower()
            if not lowered.startswith("auxiliary/scanner/"):
