import hashlib
import json
import os
from pathlib import Path

HOME = Path.home()
ROOT = HOME / ".msf4"
KEYWORDS = ("heartbleed", "heartbeat", "heart_beat")


def file_record(path, kind):
    try:
        data = path.read_bytes()
    except Exception as exc:
        return {"path": str(path), "kind": kind, "read_error": repr(exc)}
    record = {
        "path": str(path),
        "kind": kind,
        "size_bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }
    if b"\x00" in data:
        record["encoding"] = "binary; base64 follows"
        import base64
        record["content_base64"] = base64.b64encode(data).decode("ascii")
    else:
        record["encoding"] = "utf-8 with replacement for invalid bytes"
        record["content"] = data.decode("utf-8", errors="replace")
    return record


results = {
    "purpose": "Recover existing Metasploit Heartbleed execution evidence only; no scan or network request is performed.",
    "prior_finding_supplied": "A prior synthesized assessment reports a 65535-byte Heartbleed leak but does not provide the original console output or leak bytes.",
    "searched_locations": [],
    "records": [],
    "limitations": [],
}

# Metasploit's usual per-user history, console logs, and loot directories.
known = [
    (ROOT / "history", "console_history"),
    (ROOT / "logs" / "console", "console_log_directory"),
    (ROOT / "logs" / "framework.log", "framework_log"),
    (ROOT / "loot", "loot_directory"),
]

seen = set()
for location, kind in known:
    results["searched_locations"].append({"path": str(location), "kind": kind, "exists": location.exists()})
    if not location.exists():
        continue
    paths = [location] if location.is_file() else sorted(p for p in location.rglob("*") if p.is_file())
    for path in paths:
        try:
            resolved = str(path.resolve())
        except Exception:
            resolved = str(path)
        if resolved in seen:
            continue
        seen.add(resolved)
        name_match = any(word in path.name.lower() for word in KEYWORDS)
        if kind in ("console_history", "framework_log"):
            # These are direct Metasploit record sources; preserve them in full.
            results["records"].append(file_record(path, kind))
            continue
        if kind == "console_log_directory":
            # Console logs are the likely source of the original module commands and output.
            results["records"].append(file_record(path, "console_log"))
            continue
        # Loot is included when its name identifies Heartbleed/heartbeat data, or
        # when a small text artifact contains a Heartbleed marker.
        if name_match:
            results["records"].append(file_record(path, "heartbleed_named_loot"))
            continue
        try:
            size = path.stat().st_size
            if size <= 8 * 1024 * 1024:
                data = path.read_bytes()
                if b"\x00" not in data and any(word.encode() in data.lower() for word in KEYWORDS):
                    results["records"].append(file_record(path, "loot_with_heartbleed_marker"))
        except Exception as exc:
            results["limitations"].append({"path": str(path), "issue": repr(exc)})

if not results["records"]:
    results["limitations"].append(
        "No matching history, console log, or Heartbleed-related loot was readable in the inspected ~/.msf4 locations. This does not establish that records do not exist outside those locations."
    )
else:
    results["limitations"].append(
        "Only standard per-user ~/.msf4 history, logs, and loot locations were examined. Records stored elsewhere or output not persisted to disk remain unavailable to this review."
    )

print(json.dumps(results, ensure_ascii=False, indent=2))

