CONTEXT_LINES = 3


def file_metadata(path):
    st = path.stat()
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return {
        "path": str(path),
        "size_bytes": st.st_size,
        "mtime": st.st_mtime,
        "sha256": digest.hexdigest(),
    }


def files_under(directory):
    if not directory.exists():
        return []
    result = []
    for root, dirs, names in os.walk(directory):
        dirs.sort()
        for name in sorted(names):
            path = Path(root) / name
            try:
                if path.is_file():
                    result.append(path)
            except OSError:
                continue
    return result


def inspect_log(path):
    item = file_metadata(path)
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError as exc:
        item["read_error"] = str(exc)
        return item
    lines = text.splitlines()
    matching = [i for i, line in enumerate(lines) if KEYWORDS.search(line)]
    selected = set()
    for i in matching:
        selected.update(range(max(0, i - CONTEXT_LINES), min(len(lines), i + CONTEXT_LINES + 1)))
    item["total_lines"] = len(lines)
    item["keyword_match_count"] = len(matching)
    item["matching_context"] = [
        {"line": i + 1, "text": lines[i]} for i in sorted(selected)
    ]
    return item


def inspect_loot(path):
    item = file_metadata(path)
    try:
        with path.open("rb") as stream:
            raw = stream.read(MAX_LOOT_OUTPUT + 1)
    except OSError as exc:
        item["read_error"] = str(exc)
        return item
    truncated = len(raw) > MAX_LOOT_OUTPUT
    sample = raw[:MAX_LOOT_OUTPUT]
    item["content_truncated"] = truncated
    item["content_bytes_included"] = len(sample)
    try:
        decoded = sample.decode("utf-8")
        if "\x00" not in decoded:
            item["content_encoding"] = "utf-8"
            item["content"] = decoded
            return item
    except UnicodeDecodeError:
        pass
    printable = re.findall(rb"[\x20-\x7e\t\r\n]{4,}", sample)
    item["content_encoding"] = "binary; printable ASCII runs"
    item["printable_strings"] = [s.decode("ascii", errors="replace") for s in printable]
    return item


def main():
    root = Path.home() / ".msf4"
    history = root / "history"
    logs_dir = root / "logs"
    loot_dir = root / "loot"
    report = {
        "purpose": "Review existing Metasploit evidence only; no scan or Metasploit command was run.",
        "scope": str(root),
        "locations": {},
        "logs": [],
        "loot": [],
        "limitations": [],
    }
    for label, path in (("history", history), ("logs", logs_dir), ("loot", loot_dir)):
        report["locations"][label] = {"path": str(path), "exists": path.exists()}

    log_files = files_under(logs_dir)
    loot_files = files_under(loot_dir)
    report["locations"]["logs"]["file_count"] = len(log_files)
    report["locations"]["loot"]["file_count"] = len(loot_files)
    for path in log_files:
        try:
            report["logs"].append(inspect_log(path))
        except OSError as exc:
            report["logs"].append({"path": str(path), "read_error": str(exc)})
    for path in loot_files:
        try:
            report["loot"].append(inspect_loot(path))
        except OSError as exc:
            report["loot"].append({"path": str(path), "read_error": str(exc)})

    if not history.exists():
        report["limitations"].append("The standard per-user Metasploit history path does not exist; no console history is available there.")
    elif history.is_file():
        try:
            report["history"] = {**file_metadata(history), "content": history.read_text(encoding="utf-8", errors="replace")}
        except OSError as exc:
            report["history"] = {"path": str(history), "read_error": str(exc)}
    else:
        report["limitations"].append("The standard history path exists but is not a regular file; it was not interpreted as console history.")
    if not logs_dir.exists():
        report["limitations"].append("The standard per-user logs directory is absent; scan output not persisted there cannot be recovered from it.")
    if not loot_dir.exists():
        report["limitations"].append("The standard per-user loot directory is absent; no artifacts can be reviewed there.")
    if any(x.get("content_truncated") for x in report["loot"]):
        report["limitations"].append("One or more loot files exceed the 65536-byte content display limit; full-file SHA-256 and size are reported, but only the initial bytes are displayed.")
    if not any(x.get("keyword_match_count", 0) for x in report["logs"]):
        report["limitations"].append("No Heartbleed-related keyword was found in the examined log text; this does not establish that unexamined locations or non-text records lack the scan output.")
    print(json.dumps(report, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

