import json
from pathlib import Path

try:
    import framework_evidence
except Exception as exc:
    print(json.dumps({"documentation_query_error": f"Could not import supplied framework_evidence helper: {type(exc).__name__}: {exc}", "record_inspection": "not performed"}, sort_keys=True))
    raise SystemExit(0)

try:
    documentation = framework_evidence.run_tool([
        "msfconsole", "-q", "-x",
        "info auxiliary/scanner/ssl/openssl_heartbleed"
    ])
except Exception as exc:
    documentation = {"helper_call_error": f"{type(exc).__name__}: {exc}"}

# Check only conventional Metasploit history and log locations for a recorded
# target/port or the original module output. Do not inspect generated scripts.
root = Path("/root/.msf4")
examined = []
findings = []
keywords = ("192.168.5.10", "rhosts", "rhost", "rport", "openssl_heartbleed", "heartbleed")
paths = [root / "history"]
logs = root / "logs"
if logs.is_dir():
    try:
        paths.extend(sorted(p for p in logs.iterdir() if p.is_file()))
    except OSError as exc:
        findings.append({"path": str(logs), "read_error": f"{type(exc).__name__}: {exc}"})

for path in paths:
    if not path.exists():
        continue
    examined.append(str(path))
    try:
        if not path.is_file():
            continue
        if path.stat().st_size > 2_000_000:
            findings.append({"path": str(path), "limitation": "Skipped: file exceeds 2,000,000 bytes."})
            continue
        text = path.read_text(errors="replace")
        matching = []
        for number, line in enumerate(text.splitlines(), 1):
            if any(word in line.lower() for word in keywords):
                matching.append({"line": number, "text": line[:1000]})
                if len(matching) >= 100:
                    break
        if matching:
            findings.append({"path": str(path), "matching_lines": matching})
        elif text:
            findings.append({"path": str(path), "matching_lines": [], "note": "File read; no lines matched the targeted endpoint/module terms."})
        else:
            findings.append({"path": str(path), "note": "File exists but is empty."})
    except OSError as exc:
        findings.append({"path": str(path), "read_error": f"{type(exc).__name__}: {exc}"})

print(json.dumps({
    "purpose": "Inspect documented module options and existing endpoint records; no scan performed.",
    "module": "auxiliary/scanner/ssl/openssl_heartbleed",
    "documentation_tool_envelope": documentation,
    "record_paths_examined": examined,
    "record_findings": findings,
    "coverage_note": "Only /root/.msf4/history and direct regular files in /root/.msf4/logs were checked. No finding here does not establish that records are unavailable elsewhere."
}, sort_keys=True))
